=====DECISION=====
"""Deterministic accept / reject / review engine. The LLM never decides this."""

from __future__ import annotations

from .kicad.reader import ProjectState
from .kicad.state import diff_states, touches_protected
from .models import (
    ActionPlan,
    CheckResult,
    ConnectPins,
    ConnectPinToNet,
    Decision,
    EnsurePullup,
    ErcReport,
    ExecutionResult,
    ValidationReport,
    ViolationDiff,
)


def expected_pin_nets(plan: ActionPlan, before: ProjectState) -> dict[str, str]:
    """Pin -> net assignments the approved plan is allowed to create."""
    expected: dict[str, str] = {}
    for action in plan.actions:
        if isinstance(action, ConnectPins):
            for pin_ref in (action.from_pin, action.to_pin):
                reference, _, pin_key = pin_ref.partition(".")
                component = before.components.get(reference)
                pin = component.pin(pin_key) if component else None
                if pin is not None:
                    expected[f"{reference}.{pin.number}"] = action.net_name
        elif isinstance(action, ConnectPinToNet):
            reference, _, pin_key = action.pin.partition(".")
            component = before.components.get(reference)
            pin = component.pin(pin_key) if component else None
            if pin is not None:
                expected[f"{reference}.{pin.number}"] = action.net
    return expected


def _pullup_nets(plan: ActionPlan) -> list[tuple[str, str]]:
    return [(a.net, a.to_net) for a in plan.actions if isinstance(a, EnsurePullup)]


def evaluate(
    plan: ActionPlan,
    execution: ExecutionResult,
    before: ProjectState,
    after: ProjectState | None,
    erc_before: ErcReport,
    erc_after: ErcReport | None,
    violation_diff: ViolationDiff | None,
) -> tuple[Decision, str, ValidationReport]:
    checks: list[CheckResult] = []
    report = ValidationReport(erc_before=erc_before, erc_after=erc_after, violation_diff=violation_diff)

    checks.append(
        CheckResult(
            name="execution_completed",
            passed=execution.completed,
            detail=execution.error or f"{len(execution.steps)} action(s) executed",
        )
    )

    readable = after is not None
    report.project_readable = readable
    checks.append(
        CheckResult(
            name="project_readable",
            passed=readable,
            detail="schematic parsed after execution" if readable else "schematic could not be parsed",
        )
    )

    if after is None:
        report.checks = checks
        return Decision.REJECTED_AND_RESTORED, "The modified project could not be read back.", report

    state_diff = diff_states(before, after)
    report.state_diff = state_diff

    expected = expected_pin_nets(plan, before)
    created = {pin: net for pin, net in expected.items() if after.pin_nets.get(pin) == net}
    report.requested_connections_total = len(expected)
    report.requested_connections_created = len(created)
    missing = sorted(set(expected) - set(created))
    checks.append(
        CheckResult(
            name="requested_connections_created",
            passed=not missing,
            detail=f"{len(created)}/{len(expected)} created"
            + (f"; missing {', '.join(missing)}" if missing else ""),
        )
    )

    pullup_problems: list[str] = []
    for net, rail in _pullup_nets(plan):
        found = False
        for reference, component in after.components.items():
            if component.is_power or not reference.startswith("R"):
                continue
            nets = {after.pin_nets.get(f"{reference}.{pin.number}") for pin in component.pins}
            if net in nets and rail in nets:
                found = True
                break
        if not found:
            pullup_problems.append(f"{net} has no pull-up to {rail}")
    checks.append(
        CheckResult(
            name="supporting_components_present",
            passed=not pullup_problems,
            detail="; ".join(pullup_problems) or "all required pull-ups present",
        )
    )

    protected_hits = touches_protected(state_diff, plan.protected_objects)
    report.protected_modified = bool(protected_hits)
    checks.append(
        CheckResult(
            name="protected_objects_preserved",
            passed=not protected_hits,
            detail="; ".join(protected_hits) or "no protected object changed",
        )
    )

    allowed_new_components = {net for net, _ in _pullup_nets(plan)}
    unexpected: list[str] = []
    for pin, net in {**state_diff.added_pin_nets}.items():
        if expected.get(pin) == net:
            continue
        reference = pin.split(".")[0]
        if reference in state_diff.added_components and allowed_new_components:
            continue
        unexpected.append(f"{pin} joined {net}")
    for pin, (old, new) in state_diff.changed_pin_nets.items():
        if expected.get(pin) != new:
            unexpected.append(f"{pin} moved from {old} to {new}")
    for pin, net in state_diff.removed_pin_nets.items():
        unexpected.append(f"{pin} left {net}")
    for reference in state_diff.added_components:
        if not (reference.startswith("R") and allowed_new_components):
            unexpected.append(f"component {reference} was added")
    for reference in state_diff.removed_components:
        unexpected.append(f"component {reference} was removed")
    for reference, (old, new) in state_diff.changed_values.items():
        unexpected.append(f"{reference} value changed from {old} to {new}")
    report.unexpected_changes = len(unexpected)
    checks.append(
        CheckResult(
            name="no_unauthorized_changes",
            passed=not unexpected,
            detail="; ".join(unexpected) or "only approved changes were applied",
        )
    )

    erc_conclusive = erc_before.ran and erc_after is not None and erc_after.ran
    new_critical = violation_diff.new_critical if violation_diff else []
    checks.append(
        CheckResult(
            name="no_new_critical_erc_violations",
            passed=not new_critical,
            detail=(
                "; ".join(f"{v.type}: {v.description}" for v in new_critical)
                if new_critical
                else ("no new ERC errors" if erc_conclusive else "ERC could not be run")
            ),
        )
    )

    report.checks = checks
    failed = [check for check in checks if not check.passed]
    if failed:
        reason = "; ".join(f"{check.name}: {check.detail}" for check in failed)
        return Decision.REJECTED_AND_RESTORED, reason, report
    if not erc_conclusive:
        return (
            Decision.NEEDS_USER_REVIEW,
            "All structural checks passed but KiCAD ERC could not be run, so the result is unverified.",
            report,
        )
    resolved = len(violation_diff.resolved) if violation_diff else 0
    return (
        Decision.ACCEPTED,
        f"All {report.requested_connections_created} approved connections were created, "
        f"no unauthorized changes were made and no new critical ERC violations were introduced "
        f"({resolved} pre-existing violation(s) resolved).",
        report,
    )

=====INSTRUCTION=====
"""Deterministic parsing of the free-text instruction into planning parameters."""

from __future__ import annotations

import re
from dataclasses import dataclass, field

PROTOCOL_PATTERNS = {
    "I2C": r"\bi\s?[²2]\s?c\b|\bi2c\b|\btwi\b",
    "SPI": r"\bspi\b",
    "UART": r"\buart\b|\bserial\b",
}

VOLTAGE_PATTERN = r"(\d(?:[.,]\d)?)\s*[vV]\b"
PULLUP_VALUE_PATTERN = r"(\d+(?:[.,]\d+)?)\s*k(?:ilo)?\s*(?:Ω|ω|ohms?)?"
REFERENCE_PATTERN = r"\b([A-Z]{1,3}\d{1,3})\b"
PIN_PATTERN = r"\b(GPIO\s?\d{1,2}|IO\s?\d{1,2}|P[A-D]\d{1,2})\b"


@dataclass
class ParsedInstruction:
    protocol: str | None = None
    logic_voltage: str | None = None
    pullup_value: str | None = None
    sda_pin: str | None = None
    scl_pin: str | None = None
    mentioned_references: list[str] = field(default_factory=list)
    protected_objects: list[str] = field(default_factory=list)
    allow_new_components: bool = True
    raw: str = ""


def _normalize_pin(token: str) -> str:
    return token.replace(" ", "").upper()


def _pin_for_signal(text: str, signal: str) -> str | None:
    """Find the controller pin the instruction assigns to `signal`, in either word order."""
    patterns = (
        rf"(?:{signal})[^a-z0-9]{{0,12}}?" + PIN_PATTERN,
        PIN_PATTERN + rf"\s*(?:for|as)\s*(?:the\s*)?(?:{signal})",
    )
    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            return _normalize_pin(match.group(1))
    return None


def parse_instruction(text: str) -> ParsedInstruction:
    lowered = text.lower()
    parsed = ParsedInstruction(raw=text)

    for protocol, pattern in PROTOCOL_PATTERNS.items():
        if re.search(pattern, lowered):
            parsed.protocol = protocol
            break

    voltage = re.search(VOLTAGE_PATTERN, text)
    if voltage:
        parsed.logic_voltage = f"{voltage.group(1).replace(',', '.')}V"

    pullup = re.search(PULLUP_VALUE_PATTERN, lowered)
    if pullup:
        parsed.pullup_value = f"{pullup.group(1).replace(',', '.')}k"

    parsed.sda_pin = _pin_for_signal(text, r"sda|data")
    parsed.scl_pin = _pin_for_signal(text, r"scl|clock|clk")

    parsed.mentioned_references = sorted(set(re.findall(REFERENCE_PATTERN, text)))

    for sentence in re.split(r"[.\n;]", text):
        if re.search(
            r"do not (?:modify|change|touch)|don'?t (?:modify|change|touch)|keep .* unchanged|protect",
            sentence,
            re.IGNORECASE,
        ):
            parsed.protected_objects.extend(re.findall(REFERENCE_PATTERN, sentence))
            if re.search(r"\busb\b", sentence, re.IGNORECASE):
                parsed.protected_objects.extend(["USB_D+", "USB_D-", "VBUS"])
    parsed.protected_objects = sorted(set(parsed.protected_objects))

    if re.search(r"do not add|no new components|without adding", lowered):
        parsed.allow_new_components = False

    return parsed
=====GENERATOR=====
"""Turn an instruction plus real KiCAD state into a structured action plan."""

from __future__ import annotations

import re
from dataclasses import replace

from ..kicad.reader import Component, ProjectState
from ..models import (
    ActionPlan,
    Clarification,
    ConnectPins,
    ConnectPinToNet,
    EnsurePullup,
    PlanAnswers,
    Protocol,
)
from .instruction import ParsedInstruction, parse_instruction

SUPPORTED_PROTOCOLS = {Protocol.I2C.value}
CONTROLLER_LIB_HINTS = ("mcu", "esp32", "esp8266", "stm32", "atmega", "rp2040", "microcontroller", "cpu")
CONTROLLER_PIN_HINT = re.compile(r"^(GPIO|IO|P[A-D])\d+$", re.IGNORECASE)
SDA_NAMES = ("SDA", "SDIO", "I2C_SDA", "DATA")
SCL_NAMES = ("SCL", "SCK", "I2C_SCL", "CLK")
VCC_NAMES = ("VCC", "VDD", "V+", "3V3", "VIN", "VS")
GND_NAMES = ("GND", "VSS", "AGND")

VOLTAGE_RAIL_ALIASES = {
    "3.3V": ("+3V3", "3V3", "+3.3V", "VDD3V3"),
    "5V": ("+5V", "5V"),
    "1.8V": ("+1V8", "1V8"),
}


def _pin_by_names(component: Component, names: tuple[str, ...]) -> str | None:
    for candidate in names:
        pin = component.pin(candidate)
        if pin is not None:
            return pin.name
    return None


def _answered_pin(component: Component, answer: str | None) -> str | None:
    """Resolve a clarification answer such as "3:SDA", "3" or "SDA" to a pin name."""
    if not answer:
        return None
    for token in (answer, answer.split(":", 1)[0], answer.split(":", 1)[-1]):
        pin = component.pin(token.strip())
        if pin is not None:
            return pin.name
    return None


def _is_controller(component: Component) -> bool:
    lib = component.lib_id.lower()
    if any(hint in lib for hint in CONTROLLER_LIB_HINTS):
        return True
    return sum(1 for pin in component.pins if CONTROLLER_PIN_HINT.match(pin.name)) >= 2


def _known_nets(state: ProjectState) -> set[str]:
    return set(state.nets)


def _resolve_rail(state: ProjectState, voltage: str) -> str | None:
    aliases = VOLTAGE_RAIL_ALIASES.get(voltage, (voltage,))
    nets = _known_nets(state)
    for alias in aliases:
        if alias in nets:
            return alias
    return None


def _ground_net(state: ProjectState) -> str:
    for candidate in ("GND", "GNDA", "VSS"):
        if candidate in state.nets:
            return candidate
    return "GND"


def _existing_pullup(state: ProjectState, net: str, rail: str) -> tuple[str, str] | None:
    """Return (reference, value) of a resistor already tying `net` to `rail`."""
    for reference, component in state.components.items():
        if component.is_power or not reference.startswith("R"):
            continue
        pin_nets = {state.pin_nets.get(f"{reference}.{pin.number}") for pin in component.pins}
        if net in pin_nets and rail in pin_nets:
            return reference, component.value
    return None


def _supply_net(state: ProjectState, component: Component) -> str | None:
    for pin in component.pins:
        if pin.electrical_type == "power_in" and "GND" not in pin.name.upper():
            net = state.pin_nets.get(f"{component.reference}.{pin.number}")
            if net:
                return net
    return None


def _default_voltage(state: ProjectState) -> tuple[str | None, str]:
    if _resolve_rail(state, "3.3V"):
        return "3.3V", "the project only provides a 3.3 V logic rail"
    if _resolve_rail(state, "5V"):
        return "5V", "the project only provides a 5 V rail"
    return None, "no power rail could be identified"


def generate_plan(
    state: ProjectState,
    selected: list[str],
    instruction: str,
    parsed: ParsedInstruction | None = None,
    answers: PlanAnswers | None = None,
) -> ActionPlan | Clarification:
    """Deterministic I2C planner. Never guesses when the schematic is ambiguous."""
    parsed = parsed or parse_instruction(instruction)
    answers = answers or PlanAnswers()
    parsed = replace(
        parsed,
        protocol=answers.protocol or parsed.protocol,
        logic_voltage=answers.logic_voltage or parsed.logic_voltage,
    )

    unknown = [ref for ref in selected if ref not in state.components]
    if unknown:
        return Clarification(
            question=(
                f"Component(s) {', '.join(unknown)} do not exist in this project. "
                "Which components did you mean?"
            ),
            reason="unknown_component",
            options=sorted(ref for ref, c in state.components.items() if not c.is_power),
            answer_key="selection",
        )
    if len(selected) < 2:
        return Clarification(
            question="Select at least two components to connect.",
            reason="insufficient_selection",
            options=sorted(ref for ref, c in state.components.items() if not c.is_power),
            answer_key="selection",
        )

    if parsed.protocol is None:
        return Clarification(
            question="Which interface should be used to connect these components?",
            reason="protocol_not_specified",
            options=["I2C", "SPI", "UART"],
            answer_key="protocol",
        )
    if parsed.protocol not in SUPPORTED_PROTOCOLS:
        return Clarification(
            question=f"{parsed.protocol} is not supported yet. Connect these components using I2C instead?",
            reason="unsupported_protocol",
            options=["I2C"],
            answer_key="protocol",
        )

    controllers = [ref for ref in selected if _is_controller(state.components[ref])]
    peripherals = [ref for ref in selected if ref not in controllers]
    if len(controllers) != 1 or len(peripherals) != 1:
        return Clarification(
            question="Which component is the I2C controller and which is the peripheral?",
            reason="ambiguous_roles",
            options=selected,
            answer_key="selection",
        )
    controller_ref, peripheral_ref = controllers[0], peripherals[0]
    controller, peripheral = state.components[controller_ref], state.components[peripheral_ref]

    assumptions = [f"{controller_ref} is the I2C controller", f"{peripheral_ref} is the I2C peripheral"]
    warnings: list[str] = []

    voltage = parsed.logic_voltage
    if voltage is None:
        voltage, why = _default_voltage(state)
        if voltage is None:
            return Clarification(
                question="Which logic voltage should be used for this connection?",
                reason="voltage_not_specified",
                options=["3.3V", "5V"],
                answer_key="logic_voltage",
            )
        assumptions.append(f"{voltage} logic assumed because {why}")

    rail = _resolve_rail(state, voltage)
    if rail is None:
        available = sorted(v for v in VOLTAGE_RAIL_ALIASES if _resolve_rail(state, v))
        return Clarification(
            question=(
                f"The project has no {voltage} rail, so {peripheral_ref} cannot be powered at {voltage}. "
                f"Use {' or '.join(available) if available else 'another rail'} instead?"
            ),
            reason="incompatible_voltage",
            options=available,
            answer_key="logic_voltage",
        )

    controller_supply = _supply_net(state, controller)
    if controller_supply and controller_supply != rail:
        return Clarification(
            question=(
                f"{controller_ref} is powered from {controller_supply}, so a {voltage} bus would need level "
                f"shifting, which this MVP does not add. Connect the bus at {controller_supply} "
                "logic instead?"
            ),
            reason="incompatible_logic_voltage",
            options=[controller_supply, "Cancel"],
            answer_key="logic_voltage",
        )

    peripheral_sda = _answered_pin(peripheral, answers.peripheral_sda) or _pin_by_names(peripheral, SDA_NAMES)
    peripheral_scl = _answered_pin(peripheral, answers.peripheral_scl) or _pin_by_names(peripheral, SCL_NAMES)
    for label, signal, pin_name in (
        ("SDA", "data", peripheral_sda),
        ("SCL", "clock", peripheral_scl),
    ):
        if pin_name is None:
            return Clarification(
                question=(
                    f"The symbol for {peripheral_ref} does not identify its SDA/SCL pins. "
                    f"Which pin carries I2C {signal} ({label})?"
                ),
                reason="unidentified_peripheral_pins",
                options=[f"{p.number}:{p.name}" for p in peripheral.pins],
                answer_key=f"peripheral_{label.lower()}",
            )

    controller_sda = (
        _answered_pin(controller, answers.controller_sda)
        or parsed.sda_pin
        or _pin_by_names(controller, SDA_NAMES)
    )
    controller_scl = (
        _answered_pin(controller, answers.controller_scl)
        or parsed.scl_pin
        or _pin_by_names(controller, SCL_NAMES)
    )
    if controller_sda is None and controller.pin("GPIO21"):
        controller_sda = "GPIO21"
        assumptions.append("GPIO21 used for SDA (default ESP32 I2C pin)")
    if controller_scl is None and controller.pin("GPIO22"):
        controller_scl = "GPIO22"
        assumptions.append("GPIO22 used for SCL (default ESP32 I2C pin)")
    for label, pin_name in (("SDA", controller_sda), ("SCL", controller_scl)):
        if pin_name is None or controller.pin(pin_name) is None:
            return Clarification(
                question=f"Which {controller_ref} pin should be used for {label}?",
                reason="controller_pin_unresolved",
                options=[p.name for p in controller.pins if CONTROLLER_PIN_HINT.match(p.name)],
                answer_key=f"controller_{label.lower()}",
            )

    peripheral_vcc = _pin_by_names(peripheral, VCC_NAMES)
    peripheral_gnd = _pin_by_names(peripheral, GND_NAMES)
    if peripheral_vcc is None or peripheral_gnd is None:
        warnings.append(f"{peripheral_ref} has no identifiable power or ground pin; power was left unchanged")

    sda_net = state.pin_nets.get(f"{peripheral_ref}.{peripheral.pin(peripheral_sda).number}") or "I2C_SDA"
    scl_net = state.pin_nets.get(f"{peripheral_ref}.{peripheral.pin(peripheral_scl).number}") or "I2C_SCL"
    gnd_net = _ground_net(state)
    pullup_value = parsed.pullup_value or "4.7k"

    actions: list = [
        ConnectPins(
            id="action-1",
            **{"from": f"{peripheral_ref}.{peripheral_sda}", "to": f"{controller_ref}.{controller_sda}"},
            net_name=sda_net,
            purpose="I2C data",
        ),
        ConnectPins(
            id="action-2",
            **{"from": f"{peripheral_ref}.{peripheral_scl}", "to": f"{controller_ref}.{controller_scl}"},
            net_name=scl_net,
            purpose="I2C clock",
        ),
    ]
    if peripheral_vcc:
        actions.append(
            ConnectPinToNet(
                id="action-3", pin=f"{peripheral_ref}.{peripheral_vcc}", net=rail, purpose="Power"
            )
        )
    if peripheral_gnd:
        actions.append(
            ConnectPinToNet(
                id="action-4", pin=f"{peripheral_ref}.{peripheral_gnd}", net=gnd_net, purpose="Ground"
            )
        )

    next_index = len(actions) + 1
    for net in (sda_net, scl_net):
        existing = _existing_pullup(state, net, rail)
        if existing:
            assumptions.append(
                f"{net} already has pull-up {existing[0]} ({existing[1]}) to {rail}; none added"
            )
            continue
        if not parsed.allow_new_components:
            warnings.append(f"{net} has no pull-up to {rail} but adding components was not allowed")
            continue
        actions.append(
            EnsurePullup(
                id=f"action-{next_index}",
                net=net,
                to_net=rail,
                value=pullup_value,
                purpose="Bus pull-up",
            )
        )
        next_index += 1

    protected = sorted(set(parsed.protected_objects))
    return ActionPlan(
        goal=f"Connect {peripheral_ref} to {controller_ref} using I2C with {voltage} logic",
        selected_components=selected,
        protocol=Protocol.I2C,
        logic_voltage=voltage,
        assumptions=assumptions,
        warnings=warnings,
        protected_objects=protected,
        actions=actions,
    )
=====VALIDATOR=====
"""Rule-based validation of a plan before it is allowed anywhere near KiCAD."""

from __future__ import annotations

from ..kicad.reader import ProjectState
from ..models import ActionPlan, ActionType, ConnectPins, ConnectPinToNet, EnsurePullup, Protocol

ALLOWED_ACTION_TYPES = {ActionType.CONNECT_PINS, ActionType.CONNECT_PIN_TO_NET, ActionType.ENSURE_PULLUP}
GROUND_NETS = {"GND", "GNDA", "VSS", "AGND"}
POWER_NET_PREFIXES = ("+", "VCC", "VDD", "VBUS")


def _split_pin(reference_pin: str) -> tuple[str, str]:
    reference, _, pin = reference_pin.partition(".")
    return reference, pin


def _pin_exists(state: ProjectState, reference_pin: str) -> str | None:
    reference, pin_key = _split_pin(reference_pin)
    component = state.components.get(reference)
    if component is None:
        return f"component {reference} does not exist"
    if not pin_key:
        return f"no pin specified for {reference}"
    if component.pin(pin_key) is None:
        return f"pin {pin_key} does not exist on {reference}"
    return None


def _is_power_net(net: str) -> bool:
    upper = net.upper()
    return upper in GROUND_NETS or upper.startswith(POWER_NET_PREFIXES)


def validate_plan(state: ProjectState, plan: ActionPlan) -> list[str]:
    """Return a list of blocking problems; an empty list means the plan may run."""
    problems: list[str] = []

    if plan.protocol != Protocol.I2C:
        problems.append(f"protocol {plan.protocol} is not supported")
    if not plan.actions:
        problems.append("plan contains no actions")

    for reference in plan.selected_components:
        if reference not in state.components:
            problems.append(f"selected component {reference} does not exist")

    protected = {item.upper() for item in plan.protected_objects}
    seen_ids: set[str] = set()

    for action in plan.actions:
        if action.type not in ALLOWED_ACTION_TYPES:
            problems.append(f"action type {action.type} is not allowed")
            continue
        if action.id in seen_ids:
            problems.append(f"duplicate action id {action.id}")
        seen_ids.add(action.id)

        pins: list[str] = []
        nets: list[str] = []
        if isinstance(action, ConnectPins):
            pins = [action.from_pin, action.to_pin]
            nets = [action.net_name]
            if action.from_pin == action.to_pin:
                problems.append(f"{action.id}: cannot connect a pin to itself")
        elif isinstance(action, ConnectPinToNet):
            pins = [action.pin]
            nets = [action.net]
        elif isinstance(action, EnsurePullup):
            nets = [action.net, action.to_net]
            if _is_power_net(action.net):
                problems.append(f"{action.id}: refusing to pull up power net {action.net}")
            if not _is_power_net(action.to_net):
                problems.append(f"{action.id}: pull-up target {action.to_net} is not a power net")
            if action.to_net.upper() in GROUND_NETS:
                problems.append(f"{action.id}: pull-up to ground is not valid")

        for pin in pins:
            error = _pin_exists(state, pin)
            if error:
                problems.append(f"{action.id}: {error}")
                continue
            reference, pin_key = _split_pin(pin)
            component = state.components[reference]
            pin_obj = component.pin(pin_key)
            if reference.upper() in protected or pin.upper() in protected:
                problems.append(f"{action.id}: {pin} is protected and must not change")
            if isinstance(action, ConnectPinToNet) and pin_obj.electrical_type == "power_in":
                net_upper = action.net.upper()
                if "GND" in pin_obj.name.upper() and net_upper not in GROUND_NETS:
                    problems.append(f"{action.id}: ground pin {pin} would be tied to power net {action.net}")
                if "GND" not in pin_obj.name.upper() and net_upper in GROUND_NETS:
                    problems.append(f"{action.id}: power pin {pin} would be tied to ground")
            if isinstance(action, ConnectPins) and pin_obj.electrical_type == "output":
                problems.append(f"{action.id}: {pin} is an output and cannot be shared on an I2C bus")

        for net in nets:
            if not net or net.strip() != net:
                problems.append(f"{action.id}: invalid net name {net!r}")
            if net.upper() in protected:
                problems.append(f"{action.id}: net {net} is protected and must not change")

    signal_nets = {a.net_name for a in plan.actions if isinstance(a, ConnectPins)}
    if len(signal_nets) < len([a for a in plan.actions if isinstance(a, ConnectPins)]):
        problems.append("SDA and SCL must not share the same net")
    for net in signal_nets:
        if _is_power_net(net):
            problems.append(f"signal net {net} collides with a power net")

    return problems
=====LLM=====
"""Optional LLM instruction-to-plan conversion.

The LLM may only produce the same strict schema the deterministic planner uses,
and never executes anything itself. If no API key is configured, or the model
returns something that does not validate, the deterministic planner is used.
"""

from __future__ import annotations

import json
import logging

import httpx
from pydantic import ValidationError

from ..config import settings
from ..kicad.reader import ProjectState
from ..models import ActionPlan, Clarification, PlanAnswers
from .generator import generate_plan
from .instruction import parse_instruction
from .validator import validate_plan

logger = logging.getLogger(__name__)

SYSTEM_PROMPT = """You convert an electronics engineer's instruction into a strict JSON action plan
for a KiCAD schematic. Only the I2C protocol is supported. Use only components, pins and nets that
exist in the provided project state. Never invent pins. If the request is ambiguous, unsafe, or the
schematic does not identify the needed pins, return a clarification instead of a plan.

Return JSON with either:
{"plan": {...ActionPlan...}} or {"clarification": {"question": str, "reason": str, "options": [str]}}

ActionPlan fields: schema_version, goal, selected_components, protocol, logic_voltage, assumptions,
warnings, protected_objects, actions. Allowed action types:
  {"id","type":"connect_pins","from":"U2.SDA","to":"U1.GPIO21","net_name":"I2C_SDA","purpose":""}
  {"id","type":"connect_pin_to_net","pin":"U2.VCC","net":"+3V3","purpose":""}
  {"id","type":"ensure_pullup","net":"I2C_SDA","to_net":"+3V3","value":"4.7k","purpose":""}
"""


class PlanGenerationError(RuntimeError):
    pass


def _context(state: ProjectState, selected: list[str]) -> dict:
    return {
        "selected_components": selected,
        "components": state.component_summaries(),
        "nets": {name: pins for name, pins in sorted(state.nets.items())},
    }


def _call_openai(payload: dict) -> dict:
    response = httpx.post(
        f"{settings.openai_base_url}/chat/completions",
        headers={"Authorization": f"Bearer {settings.openai_api_key}"},
        json={
            "model": settings.llm_model,
            "temperature": 0,
            "response_format": {"type": "json_object"},
            "messages": [
                {"role": "system", "content": SYSTEM_PROMPT},
                {"role": "user", "content": json.dumps(payload)},
            ],
        },
        timeout=settings.llm_timeout_seconds,
    )
    response.raise_for_status()
    return json.loads(response.json()["choices"][0]["message"]["content"])


def plan_from_instruction(
    state: ProjectState,
    selected: list[str],
    instruction: str,
    answers: PlanAnswers | None = None,
) -> tuple[ActionPlan | Clarification, str]:
    """Return (plan_or_clarification, source) where source is 'llm' or 'rules'."""
    fallback = generate_plan(state, selected, instruction, parse_instruction(instruction), answers)
    if not settings.llm_enabled or (answers and answers.model_dump(exclude_none=True)):
        return fallback, "rules"

    try:
        raw = _call_openai({"instruction": instruction, "project": _context(state, selected)})
        if "clarification" in raw:
            return Clarification.model_validate(raw["clarification"]), "llm"
        plan = ActionPlan.model_validate(raw["plan"])
        problems = validate_plan(state, plan)
        if problems:
            logger.warning("LLM plan rejected by validator: %s", problems)
            return fallback, "rules"
        return plan, "llm"
    except (httpx.HTTPError, KeyError, ValueError, ValidationError) as exc:
        logger.warning("LLM planning failed (%s); using deterministic planner", exc)
        return fallback, "rules"

=====READER=====
"""Read a KiCAD schematic into a structured, comparable project state."""

from __future__ import annotations

import math
from dataclasses import dataclass, field
from pathlib import Path

from . import sexpr
from .sexpr import Symbol

POWER_LIB_PREFIX = "power:"
LABEL_NODES = ("label", "global_label", "hierarchical_label")


@dataclass(frozen=True)
class Pin:
    number: str
    name: str
    electrical_type: str
    x: float
    y: float
    angle: float


@dataclass
class Component:
    reference: str
    value: str
    lib_id: str
    x: float
    y: float
    angle: float
    uuid: str
    pins: list[Pin] = field(default_factory=list)
    is_power: bool = False

    def pin(self, key: str) -> Pin | None:
        wanted = key.strip().upper()
        for pin in self.pins:
            if pin.name.upper() == wanted or pin.number.upper() == wanted:
                return pin
        return None


@dataclass
class ProjectState:
    """Normalized schematic state used for planning, diffing and validation."""

    project_dir: Path
    schematic_path: Path
    components: dict[str, Component]
    nets: dict[str, list[str]]
    pin_nets: dict[str, str]
    pin_positions: dict[str, tuple[float, float]]

    def pin_position(self, reference: str, pin_key: str) -> tuple[float, float] | None:
        component = self.components.get(reference)
        if component is None:
            return None
        pin = component.pin(pin_key)
        if pin is None:
            return None
        return self.pin_positions.get(f"{reference}.{pin.number}")

    def component_summaries(self) -> list[dict]:
        return [
            {
                "reference": comp.reference,
                "value": comp.value,
                "lib_id": comp.lib_id,
                "is_power": comp.is_power,
                "pins": [
                    {
                        "number": pin.number,
                        "name": pin.name,
                        "type": pin.electrical_type,
                        "net": self.pin_nets.get(f"{comp.reference}.{pin.number}"),
                    }
                    for pin in comp.pins
                ],
            }
            for comp in sorted(self.components.values(), key=lambda c: c.reference)
            if not comp.is_power
        ]

    def to_dict(self) -> dict:
        return {
            "components": {
                ref: {"value": c.value, "lib_id": c.lib_id, "is_power": c.is_power}
                for ref, c in sorted(self.components.items())
            },
            "pin_nets": dict(sorted(self.pin_nets.items())),
            "nets": {name: sorted(pins) for name, pins in sorted(self.nets.items())},
        }


def _key(x: float, y: float) -> tuple[float, float]:
    return (round(x, 3), round(y, 3))


def _transform(
    sx: float, sy: float, angle: float, mirror: str | None, px: float, py: float
) -> tuple[float, float]:
    """Absolute sheet position of a library pin placed on a symbol instance."""
    x, y = px, -py
    if mirror == "y":
        x = -x
    elif mirror == "x":
        y = -y
    rad = math.radians(angle)
    cos_a, sin_a = math.cos(rad), math.sin(rad)
    rx = x * cos_a + y * sin_a
    ry = -x * sin_a + y * cos_a
    return sx + rx, sy + ry


class _UnionFind:
    def __init__(self) -> None:
        self.parent: dict[tuple[float, float], tuple[float, float]] = {}

    def find(self, item: tuple[float, float]) -> tuple[float, float]:
        self.parent.setdefault(item, item)
        root = item
        while self.parent[root] != root:
            root = self.parent[root]
        while self.parent[item] != root:
            self.parent[item], item = root, self.parent[item]
        return root

    def union(self, a: tuple[float, float], b: tuple[float, float]) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra != rb:
            self.parent[rb] = ra


def _lib_symbol_pins(lib_symbol: list) -> list[Pin]:
    pins: list[Pin] = []
    for unit in sexpr.find_all(lib_symbol, "symbol"):
        for pin_node in sexpr.find_all(unit, "pin"):
            at = sexpr.find(pin_node, "at")
            name_node = sexpr.find(pin_node, "name")
            number_node = sexpr.find(pin_node, "number")
            if at is None or name_node is None or number_node is None:
                continue
            pins.append(
                Pin(
                    number=sexpr.atom(number_node),
                    name=sexpr.atom(name_node),
                    electrical_type=sexpr.atom(pin_node),
                    x=sexpr.number(at, 1),
                    y=sexpr.number(at, 2),
                    angle=sexpr.number(at, 3) if len(at) > 3 else 0.0,
                )
            )
    return pins


def _property(symbol_node: list, key: str) -> str | None:
    for prop in sexpr.find_all(symbol_node, "property"):
        if sexpr.atom(prop, 1) == key:
            return sexpr.atom(prop, 2)
    return None


def find_schematic(project_dir: Path) -> Path:
    schematics = sorted(project_dir.glob("*.kicad_sch"))
    if not schematics:
        raise FileNotFoundError(f"no .kicad_sch file found in {project_dir}")
    pro = sorted(project_dir.glob("*.kicad_pro"))
    if pro:
        preferred = project_dir / f"{pro[0].stem}.kicad_sch"
        if preferred.exists():
            return preferred
    return schematics[0]


def read_project(project_dir: Path) -> ProjectState:
    project_dir = Path(project_dir)
    schematic_path = find_schematic(project_dir)
    doc = sexpr.loads(schematic_path.read_text())

    lib_symbols: dict[str, list[Pin]] = {}
    lib_node = sexpr.find(doc, "lib_symbols")
    if lib_node is not None:
        for lib_symbol in sexpr.find_all(lib_node, "symbol"):
            lib_symbols[sexpr.atom(lib_symbol)] = _lib_symbol_pins(lib_symbol)

    uf = _UnionFind()
    for wire in sexpr.find_all(doc, "wire"):
        pts = sexpr.find(wire, "pts")
        if pts is None:
            continue
        points = [_key(sexpr.number(p, 1), sexpr.number(p, 2)) for p in sexpr.find_all(pts, "xy")]
        for point in points[1:]:
            uf.union(points[0], point)

    components: dict[str, Component] = {}
    pin_points: dict[str, tuple[float, float]] = {}
    label_at_point: dict[tuple[float, float], str] = {}

    for symbol_node in sexpr.find_all(doc, "symbol"):
        lib_id_node = sexpr.find(symbol_node, "lib_id")
        at = sexpr.find(symbol_node, "at")
        if lib_id_node is None or at is None:
            continue
        lib_id = sexpr.atom(lib_id_node)
        reference = _property(symbol_node, "Reference") or ""
        value = _property(symbol_node, "Value") or ""
        uuid_node = sexpr.find(symbol_node, "uuid")
        mirror_node = sexpr.find(symbol_node, "mirror")
        mirror = sexpr.atom(mirror_node) if mirror_node is not None else None
        sx, sy = sexpr.number(at, 1), sexpr.number(at, 2)
        angle = sexpr.number(at, 3) if len(at) > 3 else 0.0
        is_power = lib_id.startswith(POWER_LIB_PREFIX)
        comp = Component(
            reference=reference,
            value=value,
            lib_id=lib_id,
            x=sx,
            y=sy,
            angle=angle,
            uuid=sexpr.atom(uuid_node) if uuid_node is not None else "",
            pins=lib_symbols.get(lib_id, []),
            is_power=is_power,
        )
        if not reference:
            continue
        components[reference] = comp
        for pin in comp.pins:
            point = _key(*_transform(sx, sy, angle, mirror, pin.x, pin.y))
            pin_points[f"{reference}.{pin.number}"] = point
            if is_power:
                label_at_point.setdefault(point, value)

    for label_kind in LABEL_NODES:
        for label in sexpr.find_all(doc, label_kind):
            at = sexpr.find(label, "at")
            if at is None:
                continue
            label_at_point[_key(sexpr.number(at, 1), sexpr.number(at, 2))] = sexpr.atom(label)

    # Labels sharing a name are electrically the same net (global labels / power).
    name_roots: dict[str, tuple[float, float]] = {}
    for point, name in label_at_point.items():
        if name in name_roots:
            uf.union(name_roots[name], point)
        else:
            name_roots[name] = point

    pin_nets: dict[str, str] = {}
    nets: dict[str, list[str]] = {}
    root_names: dict[tuple[float, float], str] = {}
    for point, name in label_at_point.items():
        root_names.setdefault(uf.find(point), name)

    for pin_key, point in sorted(pin_points.items()):
        reference = pin_key.split(".")[0]
        if components[reference].is_power:
            continue
        root = uf.find(point)
        net_name = root_names.get(root)
        if net_name is None:
            connected = [k for k, p in pin_points.items() if uf.find(p) == root]
            if len(connected) < 2:
                continue
            net_name = f"Net-({sorted(connected)[0]})"
            root_names[root] = net_name
        pin_nets[pin_key] = net_name
        nets.setdefault(net_name, []).append(pin_key)

    return ProjectState(
        project_dir=project_dir,
        schematic_path=schematic_path,
        components=components,
        nets=nets,
        pin_nets=pin_nets,
        pin_positions=pin_points,
    )


def pin_net(state: ProjectState, reference: str, pin_key: str) -> str | None:
    comp = state.components.get(reference)
    if comp is None:
        return None
    pin = comp.pin(pin_key)
    if pin is None:
        return None
    return state.pin_nets.get(f"{reference}.{pin.number}")


__all__ = [
    "Component",
    "Pin",
    "ProjectState",
