"""Minimal S-expression parser/serializer for KiCAD files."""

from __future__ import annotations

from collections.abc import Iterator
from dataclasses import dataclass
from typing import Union

Atom = Union[str, "Symbol"]
Node = Union[Atom, list]  # noqa: UP007 - recursive alias needs typing.Union on 3.10


@dataclass(frozen=True)
class Symbol:
    """A bare (unquoted) S-expression token."""

    value: str

    def __str__(self) -> str:
        return self.value


class SexprError(ValueError):
    pass


def _tokenize(text: str) -> Iterator[tuple[str, str]]:
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch in " \t\r\n":
            i += 1
            continue
        if ch in "()":
            yield ("paren", ch)
            i += 1
            continue
        if ch == '"':
            i += 1
            buf: list[str] = []
            while i < n:
                c = text[i]
                if c == "\\":
                    if i + 1 >= n:
                        raise SexprError("unterminated escape in string")
                    nxt = text[i + 1]
                    buf.append({"n": "\n", "t": "\t", "r": "\r"}.get(nxt, nxt))
                    i += 2
                    continue
                if c == '"':
                    i += 1
                    break
                buf.append(c)
                i += 1
            else:
                raise SexprError("unterminated string")
            yield ("string", "".join(buf))
            continue
        start = i
        while i < n and text[i] not in ' \t\r\n()"':
            i += 1
        yield ("symbol", text[start:i])


def loads(text: str) -> list:
    """Parse a KiCAD S-expression document into nested lists."""
    stack: list[list] = []
    root: list | None = None
    for kind, value in _tokenize(text):
        if kind == "paren" and value == "(":
            new: list = []
            if stack:
                stack[-1].append(new)
            stack.append(new)
            continue
        if kind == "paren" and value == ")":
            if not stack:
                raise SexprError("unbalanced closing paren")
            done = stack.pop()
            if not stack:
                root = done
            continue
        token: Atom = value if kind == "string" else Symbol(value)
        if not stack:
            raise SexprError("atom outside of any expression")
        stack[-1].append(token)
    if stack:
        raise SexprError("unbalanced opening paren")
    if root is None:
        raise SexprError("empty document")
    return root


def _quote(value: str) -> str:
    escaped = value.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")
    return f'"{escaped}"'


def dumps(node: Node, indent: int = 0) -> str:
    """Serialize a node back to KiCAD-style S-expression text."""
    pad = "\t" * indent
    if isinstance(node, Symbol):
        return pad + node.value
    if isinstance(node, str):
        return pad + _quote(node)
    if not node:
        return pad + "()"
    head = node[0]
    if all(not isinstance(child, list) for child in node):
        inline = " ".join(dumps(child, 0) for child in node)
        return f"{pad}({inline})"
    parts = [f"{pad}({dumps(head, 0)}"]
    for child in node[1:]:
        if isinstance(child, list):
            parts.append("\n" + dumps(child, indent + 1))
        else:
            parts.append(" " + dumps(child, 0))
    parts.append("\n" + pad + ")")
    return "".join(parts)


def find_all(node: list, name: str) -> list[list]:
    """Direct children of `node` whose head symbol is `name`."""
    out = []
    for child in node[1:] if node and isinstance(node[0], Symbol) else node:
        if isinstance(child, list) and child and isinstance(child[0], Symbol) and child[0].value == name:
            out.append(child)
    return out


def find(node: list, name: str) -> list | None:
    matches = find_all(node, name)
    return matches[0] if matches else None


def atom(node: list, index: int = 1) -> str:
    """Value of a positional atom, e.g. atom(["uuid", "abc"]) -> "abc"."""
    value = node[index]
    return value.value if isinstance(value, Symbol) else value


def number(node: list, index: int = 1) -> float:
    return float(atom(node, index))
=====WRITER rest=====


def _effects(justify: str | None = None) -> list:
    effects: list = [S("effects"), [S("font"), [S("size"), S("1.27"), S("1.27")]]]
    if justify:
        effects.append([S("justify"), S(justify)])
    return effects


def has_global_label(doc: list, name: str, x: float, y: float) -> bool:
    for label in sexpr.find_all(doc, "global_label"):
        at = sexpr.find(label, "at")
        if at is None:
            continue
        if (
            sexpr.atom(label) == name
            and abs(sexpr.number(at, 1) - x) < 0.01
            and abs(sexpr.number(at, 2) - y) < 0.01
        ):
            return True
    return False


def add_global_label(doc: list, name: str, x: float, y: float, angle: float = 0) -> bool:
    """Attach a named global label at a sheet coordinate (idempotent)."""
    if has_global_label(doc, name, x, y):
        return False
    label = [
        S("global_label"),
        name,
        [S("shape"), S("bidirectional")],
        [S("at"), S(_fmt(x)), S(_fmt(y)), S(_fmt(angle))],
        [S("fields_autoplaced"), S("yes")],
        _effects("left"),
        [S("uuid"), new_uuid()],
        [
            S("property"),
            "Intersheetrefs",
            "${INTERSHEET_REFS}",
            [S("at"), S(_fmt(x)), S(_fmt(y)), S(_fmt(angle))],
            [S("effects"), [S("font"), [S("size"), S("1.27"), S("1.27")]], [S("hide"), S("yes")]],
        ],
    ]
    doc.append(label)
    return True


def _fmt(value: float) -> str:
    return f"{value:g}"


def ensure_lib_symbol(doc: list, lib_id: str, definition: str) -> None:
    lib_node = sexpr.find(doc, "lib_symbols")
    if lib_node is None:
        lib_node = [S("lib_symbols")]
        doc.insert(1, lib_node)
    for symbol in sexpr.find_all(lib_node, "symbol"):
        if sexpr.atom(symbol) == lib_id:
            return
    lib_node.append(sexpr.loads(definition))


def add_symbol_instance(
    doc: list,
    lib_id: str,
    reference: str,
    value: str,
    x: float,
    y: float,
    project_name: str,
    angle: float = 0,
) -> str:
    """Place a symbol instance on the sheet and return its uuid."""
    instance_uuid = new_uuid()
    symbol = [
        S("symbol"),
        [S("lib_id"), lib_id],
        [S("at"), S(_fmt(x)), S(_fmt(y)), S(_fmt(angle))],
        [S("unit"), S("1")],
        [S("exclude_from_sim"), S("no")],
        [S("in_bom"), S("yes")],
        [S("on_board"), S("yes")],
        [S("dnp"), S("no")],
        [S("uuid"), instance_uuid],
        [
            S("property"),
            "Reference",
            reference,
            [S("at"), S(_fmt(x + 2.54)), S(_fmt(y - 1.27)), S("0")],
            _effects("left"),
        ],
        [
            S("property"),
            "Value",
            value,
            [S("at"), S(_fmt(x + 2.54)), S(_fmt(y + 1.27)), S("0")],
            _effects("left"),
        ],
        [
            S("instances"),
            [
                S("project"),
                project_name,
                [
                    S("path"),
                    f"/{root_uuid(doc)}",
                    [S("reference"), reference],
                    [S("unit"), S("1")],
                ],
            ],
        ],
    ]
    doc.append(symbol)
    return instance_uuid


def next_reference(doc: list, prefix: str) -> str:
    used = set()
    for symbol in sexpr.find_all(doc, "symbol"):
        for prop in sexpr.find_all(symbol, "property"):
            if sexpr.atom(prop, 1) == "Reference":
                used.add(sexpr.atom(prop, 2))
    index = 1
    while f"{prefix}{index}" in used:
        index += 1
    return f"{prefix}{index}"


def free_area(doc: list) -> tuple[float, float]:
    """A sheet coordinate below every existing symbol, used for added parts."""
    max_y = 0.0
    min_x = 1e9
    for symbol in sexpr.find_all(doc, "symbol"):
        at = sexpr.find(symbol, "at")
        if at is None:
            continue
        max_y = max(max_y, sexpr.number(at, 2))
        min_x = min(min_x, sexpr.number(at, 1))
    if min_x > 1e8:
        min_x = 50.0
    return min_x, max_y + 25.4

