const { chromium } = require('playwright');
const TARGET_URL = 'http://localhost:3000';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));

  await page.goto(TARGET_URL, { waitUntil: 'networkidle' });
  await page.locator('li', { hasText: 'esp32_i2c_board' }).getByRole('button', { name: 'Open' }).click();
  await page.waitForSelector('text=Select components and describe the change');
  console.log('opened esp32_i2c_board (has a PCB, so DRC runs)');

  // PCB toggle should be enabled for this project.
  console.log('PCB view enabled:', await page.getByRole('button', { name: 'PCB' }).isEnabled());

  for (const part of ['ESP32-WROOM-32', 'TMP102']) {
    await page.locator('label.flex', { hasText: part }).locator('input').check();
  }
  await page.getByRole('button', { name: 'Generate plan' }).click();
  await page.waitForSelector('text=Review the proposed actions', { timeout: 30000 });
  await page.getByRole('button', { name: 'Approve and execute' }).click();
  await page.waitForSelector('text=Validation report', { timeout: 60000 });

  const section = await page.locator('section', { hasText: 'Validation report' }).textContent();
  const flat = section.replace(/\s+/g, ' ').trim();
  console.log('\nDECISION LINE:', flat.match(/(accepted|rejected and restored|needs user review)[^·]*/i)?.[0]?.slice(0, 110));
  for (const key of ['ERC before', 'DRC before', 'files changed']) {
    const m = flat.match(new RegExp(key + '[^A-Z]{0,150}'));
    console.log(`${key}:`, m ? m[0].trim().slice(0, 130) : 'NOT SHOWN');
  }
  const checks = await page.locator('section', { hasText: 'Validation report' }).locator('li').allTextContents();
  console.log('\nCHECKS:');
  checks.forEach((c) => console.log('  -', c.replace(/\s+/g, ' ').trim().slice(0, 120)));

  await page.screenshot({ path: '/tmp/kicad-ui-report.png', fullPage: true });
  console.log('\nscreenshot: /tmp/kicad-ui-report.png');
  console.log('CONSOLE ERRORS:', errors.length ? errors : 'none');
  await browser.close();
})();
